<?php
use App\Entities\TenantContext;
use App\Services\Website\MediaService;
use CodeIgniter\Test\CIUnitTestCase;
use CodeIgniter\Test\DatabaseTestTrait;
/** Exercises public/private and cross-tenant derivative policy at the media service boundary. @internal */
final class WebsitePhase4MediaVisibilityTest extends CIUnitTestCase { use DatabaseTestTrait; protected $migrate=true; protected $namespace='App'; public function testPrivateMediaIsRejectedForAnonymousDerivative():void{$id=$this->fixture('private');$this->expectException(\InvalidArgumentException::class);(new MediaService())->publicDerivative($id);} public function testCrossTenantMediaIsRejectedBeforeStorageLookup():void{$id=$this->fixture('public');$this->context($this->tenant('other'),'other');$this->expectException(\InvalidArgumentException::class);(new MediaService())->publicDerivative($id);} private function fixture(string $visibility):int{$tenant=$this->tenant('media-'.$visibility);$this->context($tenant,'media-'.$visibility);$this->db->table('media_files')->insert(['tenant_id'=>$tenant,'original_name'=>'a.jpg','stored_name'=>'a.jpg','storage_disk'=>'local','storage_path'=>'a.jpg','mime_type'=>'image/jpeg','extension'=>'jpg','size_bytes'=>1,'width'=>1,'height'=>1,'checksum_sha256'=>str_repeat('a',64),'visibility'=>$visibility,'category'=>'gallery_image','derivatives'=>'{}']);return (int)$this->db->insertID();} private function tenant(string $slug):int{$this->db->table('tenants')->insert(['school_name'=>$slug,'slug'=>$slug,'status'=>'active']);return (int)$this->db->insertID();}private function context(int $id,string $slug):void{service('tenantContextManager')->set(new TenantContext($id,$slug,'route_slug'));}}
